#!/usr/bin/env sh
set -eu

usage() {
  cat <<'EOF'
Usage: sh scripts/init.sh [options]
  --system         Install wrappers in /usr/local/bin (default for root)
  --user           Install wrappers in ~/.local/bin (default otherwise)
  --bin-dir PATH   Use a custom wrapper directory
  --no-path        Do not edit a shell profile
  --force          Replace existing wrappers that were not generated by tedit
  --show           Print paths without installing or authenticating
  -h, --help       Show help
Environment: TEDIT_REPO, XDG_DATA_HOME, LOG_FILE, VERBOSE=1
EOF
}

MODE=auto
DEST_BIN=
NO_PATH=0
FORCE=0
SHOW=0
while [ "$#" -gt 0 ]; do
  case "$1" in
    --system) MODE=system ;;
    --user) MODE=user ;;
    --bin-dir)
      shift
      [ "$#" -gt 0 ] && [ -n "$1" ] || { printf '%s\n' 'ERROR: --bin-dir needs a path' >&2; exit 1; }
      DEST_BIN=$1 ;;
    --no-path) NO_PATH=1 ;;
    --force) FORCE=1 ;;
    --show) SHOW=1 ;;
    -h|--help) usage; exit 0 ;;
    *) printf 'ERROR: unknown option: %s\n' "$1" >&2; exit 1 ;;
  esac
  shift
done
SCRIPT_DIR=$(CDPATH= cd -P -- "$(dirname -- "$0")" && pwd)
# shellcheck source=scripts/common.sh
. "$SCRIPT_DIR/common.sh"
tedit_setup init
REPO_DIR=$(tedit_find_repo "${TEDIT_REPO:-}") || tedit_die 'Cannot find the source checkout. Set TEDIT_REPO.'
for target in install update uninstall; do
  [ -f "$REPO_DIR/scripts/$target.sh" ] || tedit_die "Missing scripts/$target.sh"
done
if [ "$MODE" = auto ]; then
  if [ "$TEDIT_UID" -eq 0 ]; then MODE=system; else MODE=user; fi
fi
if [ "$MODE" = system ]; then
  DEST_BIN=${DEST_BIN:-/usr/local/bin}
  MARKER=/usr/local/share/tedit/repo
else
  : "${HOME:?HOME is required for user wrappers}"
  DEST_BIN=${DEST_BIN:-$HOME/.local/bin}
  MARKER=${XDG_DATA_HOME:-$HOME/.local/share}/tedit/repo
fi
DEST_BIN=$(tedit_absolute "$DEST_BIN")
MARKER=$(tedit_absolute "$MARKER")
if [ "$SHOW" -eq 1 ]; then
  printf 'REPO_DIR=%s\nMODE=%s\nDEST_BIN=%s\nMARKER=%s\n' "$REPO_DIR" "$MODE" "$DEST_BIN" "$MARKER"
  exit 0
fi

# Preflight all names before replacing anything. Do not follow foreign symlinks.
for name in tedit-install tedit-update tedit-uninstall; do
  destination=$DEST_BIN/$name
  [ ! -d "$destination" ] || tedit_die "Refusing to replace a directory: $destination"
  if [ -e "$destination" ] || [ -L "$destination" ]; then
    if [ "$FORCE" -eq 0 ]; then
      if [ -L "$destination" ] || ! grep -q '^# Generated by tedit init' "$destination"; then
        tedit_die "Refusing to overwrite $destination; use --force to replace it."
      fi
    fi
  fi
done
tedit_say ":: Installing wrappers for $REPO_DIR"
tedit_say "Log: $TEDIT_LOG"
for target in install update uninstall; do
  wrapper=$TEDIT_WORK/tedit-$target
  {
    printf '%s\n' '#!/usr/bin/env sh' '# Generated by tedit init' 'set -eu'
    printf 'DEFAULT_REPO=%s\n' "$(tedit_quote "$REPO_DIR")"
    printf 'MARKER=%s\n' "$(tedit_quote "$MARKER")"
    printf 'TARGET=%s\n' "$(tedit_quote "scripts/$target.sh")"
    printf 'TEDIT_WRAPPER_BIN=%s\n' "$(tedit_quote "$DEST_BIN")"
    cat <<'EOF'
REPO_DIR=${TEDIT_REPO:-}
if [ -z "$REPO_DIR" ] && [ -r "$MARKER" ]; then IFS= read -r REPO_DIR <"$MARKER" || :; fi
REPO_DIR=${REPO_DIR:-$DEFAULT_REPO}
if [ ! -f "$REPO_DIR/src/tedit.cpp" ] || [ ! -f "$REPO_DIR/$TARGET" ]; then
  printf 'ERROR: tedit checkout is missing at %s; set TEDIT_REPO or rerun init.sh.\n' "$REPO_DIR" >&2
  exit 1
fi
TEDIT_WRAPPER_MARKER=$MARKER
export TEDIT_WRAPPER_BIN TEDIT_WRAPPER_MARKER
exec sh "$REPO_DIR/$TARGET" "$@"
EOF
  } >"$wrapper"
  tedit_place "$wrapper" "$DEST_BIN/tedit-$target" 0755 || tedit_die "Could not install tedit-$target."
done
printf '%s\n' "$REPO_DIR" >"$TEDIT_WORK/repo"
tedit_place "$TEDIT_WORK/repo" "$MARKER" 0644 || tedit_die 'Could not record the source checkout.'
if [ "$MODE" = user ] && [ "$NO_PATH" -eq 0 ]; then tedit_add_path "$DEST_BIN" init; fi
tedit_say "Wrappers installed in $DEST_BIN"
